// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IAction} from "pecunity-strategy-builder/contracts/interfaces/IAction.sol";
import {ITokenGetter} from "pecunity-strategy-builder/contracts/interfaces/ITokenGetter.sol";
import {ITradingPortal} from "../external/ITradingPortal.sol";
import {ITradingReader} from "../external/ITradingReader.sol";
import {IBook} from "../external/IBook.sol";
import {ITrading} from "../external/ITrading.sol";
import {IPriceFacade} from "../external/IPriceFacade.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IPerpPositionAction} from "./interfaces/IPerpPositionAction.sol";

/// @title PerpPositionAction
/// @notice Strategy Builder action for opening and closing ApolloX perpetual positions
/// @dev This contract does NOT execute trades directly.
///      It returns a sequence of PluginExecution objects that must be executed
///      by the Pecunity Strategy Executor.
///      Prices are fetched from the ApolloX router oracle.
///      Position sizing uses fixed-point math aligned with ApolloX conventions.
contract PerpPositionAction is IPerpPositionAction, ITokenGetter {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Constants          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @dev Quantity decimals used by ApolloX (1e10)
    uint128 constant QTY_DECIMALS = 10 ** 10;

    /// @dev Price decimals used by ApolloX oracle (1e8)
    uint128 constant PRICE_DECIMALS = 10 ** 8;

    /// @dev Leverage normalization factor (ApolloX uses 1000 = 1x)
    uint128 constant LEVERAGE_FACTOR = 1000;

    /// @dev Percentage base (1000 = 100%)
    uint256 constant PERCENTAGE_DECIMALS = 1000;

    /// @dev Percentage slippage (1000 = 100%)
    uint64 constant SLIPPAGE_DECIMALS = 1000;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       StateVariable       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice ApolloX router address (oracle, trading portal, reader)
    address public immutable apolloXRouter;

    /// @notice Broker ID registered with ApolloX
    uint24 public immutable brokerId;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Constructor         ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @param _apolloXRouter ApolloX router address
    /// @param _brokerId Broker ID used for trade attribution
    constructor(address _apolloXRouter, uint24 _brokerId) {
        apolloXRouter = _apolloXRouter;
        brokerId = _brokerId;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Position Actions       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Builds execution steps to open a perpetual position
    /// @dev Returns two PluginExecutions:
    ///      1. ERC20 approve for margin token
    ///      2. openMarketTrade call to ApolloX
    ///
    /// @param tokenIn Margin token (e.g. USDC)
    /// @param baseToken Base asset of the market (e.g. BTC)
    /// @param isLong True for long, false for short
    /// @param amount Margin amount (tokenIn decimals)
    /// @param leverage Leverage scaled by 1000 (1000 = 1x)
    /// @param slippage Slippage tolerance factor used to derive the execution price.
    ///        Expressed as a percentage multiplier:
    ///        - For longs: executionPrice = basePrice * 1000 / slippage
    ///        - For shorts: executionPrice = basePrice * slippage / 1000
    ///        Example:
    ///        slippage = 1010 allows ~1% unfavorable price movement.
    ///        slippage = 1050 allows ~5% unfavorable price movement.
    ///
    /// @return executions Array of plugin executions
    function openPosition(
        address tokenIn,
        address baseToken,
        bool isLong,
        uint256 amount,
        uint256 leverage,
        uint64 slippage
    ) public view returns (PluginExecution[] memory) {
        if (amount == 0) revert ZeroAmount();
        if (leverage == 0) revert InvalidLeverage();

        uint256 basePrice = IPriceFacade(apolloXRouter).getPrice(baseToken);
        if (basePrice == 0) revert InvalidBasePrice(baseToken);

        /// qty = (amount * leverage) / basePrice / LEVERAGE_FACTOR
        uint256 positionQty = (amount * leverage) / basePrice / LEVERAGE_FACTOR;

        if (positionQty == 0) revert PositionQtyTooSmall();

        PluginExecution[] memory executions = new PluginExecution[](2);

        executions[0] = _approveToken(tokenIn, amount);

        IBook.OpenDataInput memory openDataInput = IBook.OpenDataInput({
            pairBase: baseToken,
            isLong: isLong,
            tokenIn: tokenIn,
            amountIn: uint96(amount),
            qty: uint80(positionQty),
            /// @dev Slight price offset to reduce rejection risk
            price: isLong
                ? (uint64(basePrice) * SLIPPAGE_DECIMALS) / slippage
                : (uint64(basePrice) * slippage) / SLIPPAGE_DECIMALS,
            stopLoss: 0,
            takeProfit: 0,
            broker: brokerId
        });

        executions[1] = PluginExecution({
            target: apolloXRouter,
            value: 0,
            data: abi.encodeCall(
                ITradingPortal.openMarketTrade,
                (openDataInput)
            )
        });

        return executions;
    }

    /// @notice Opens a position using a percentage of an account balance
    /// @dev Reads token balance off-chain safe (view-only)
    ///
    /// @param account Account holding margin tokens
    /// @param tokenIn Margin token
    /// @param baseToken Base market token
    /// @param isLong Long or short
    /// @param percentage Percentage of balance (1000 = 100%)
    /// @param leverage Leverage scaled by 1000
    /// @param slippage Slippage tolerance factor used to derive the execution price.
    ///        Expressed as a percentage multiplier:
    ///        - For longs: executionPrice = basePrice * 100 / slippage
    ///        - For shorts: executionPrice = basePrice * slippage / 100
    ///        Example:
    ///        slippage = 101 allows ~1% unfavorable price movement.
    ///        slippage = 105 allows ~5% unfavorable price movement.
    ///
    /// @return executions Plugin executions
    function openPositionPercentage(
        address account,
        address tokenIn,
        address baseToken,
        bool isLong,
        uint256 percentage,
        uint256 leverage,
        uint64 slippage
    ) external view returns (PluginExecution[] memory) {
        uint256 amount = (IERC20(tokenIn).balanceOf(account) * percentage) /
            PERCENTAGE_DECIMALS;

        return
            openPosition(
                tokenIn,
                baseToken,
                isLong,
                amount,
                leverage,
                slippage
            );
    }

    /// @notice Builds execution to close a perpetual position
    /// @param positionId ApolloX position hash
    /// @return executions Single execution calling closeTrade
    function closePosition(
        bytes32 positionId
    ) external view returns (PluginExecution[] memory) {
        PluginExecution[] memory executions = new PluginExecution[](1);

        executions[0] = PluginExecution({
            target: apolloXRouter,
            value: 0,
            data: abi.encodeCall(ITradingPortal.closeTrade, (positionId))
        });

        return executions;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃      Token Resolution     ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Resolves which token is used by a given function selector
    /// @dev Used by Strategy Builder for balance & allowance checks
    ///
    /// @param selector Function selector
    /// @param params ABI-encoded function parameters
    /// @return token Address of the involved ERC20 token
    function getTokenForSelector(
        bytes4 selector,
        bytes memory params
    ) external view returns (address token) {
        if (selector == IPerpPositionAction.openPosition.selector) {
            (token, , , , ) = abi.decode(
                params,
                (address, address, bool, uint256, uint256)
            );
            return token;
        }

        if (selector == IPerpPositionAction.openPositionPercentage.selector) {
            (, token, , , , ) = abi.decode(
                params,
                (address, address, address, bool, uint256, uint256)
            );
            return token;
        }

        if (selector == IPerpPositionAction.closePosition.selector) {
            bytes32 positionId = abi.decode(params, (bytes32));
            return
                ITradingReader(apolloXRouter)
                    .getPositionByHashV2(positionId)
                    .marginToken;
        }

        revert InvalidSelector();
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Metadata           ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Unique action identifier
    function identifier() external pure returns (bytes4) {
        return bytes4(keccak256("apx-perp-position-1.0.0"));
    }

    /// @notice ERC165 support check
    function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
        return interfaceId == type(IAction).interfaceId;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Internal           ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @dev Builds ERC20 approval execution
    function _approveToken(
        address token,
        uint256 amount
    ) internal view returns (PluginExecution memory) {
        return
            PluginExecution({
                target: token,
                value: 0,
                data: abi.encodeCall(IERC20.approve, (apolloXRouter, amount))
            });
    }
}

contracts/apx-finance/condition/FundingR.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseCondition} from "pecunity-strategy-builder/contracts/condition/BaseCondition.sol";
import {ITradingCore} from "../external/ITradingCore.sol";
import {ITradingReader} from "../external/ITradingReader.sol";
import {IPairsManager, PairMaxOiAndFundingFeeConfig} from "../external/IPairsManager.sol";
import {SignedMath} from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import {IFundingRateCondition} from "./interfaces/IFundingRateCondition.sol";

/// @title FundingRateCondition
/// @author Pecunity
/// @notice Strategy condition that evaluates a position's funding rate
/// @dev This contract is designed for the Pecunity Strategy Builder.
///      It implements a funding rate based condition used to evaluate
///      perpetual market imbalance for long or short positions.
///      Each condition belongs to a wallet and is identified by an ID.
///      Funding rates are derived dynamically from open interest data
///      and may include an optional delta percentage threshold.
///      Conditions may be updateable depending on their configuration.
contract FundingRateCondition is BaseCondition, IFundingRateCondition {
    using SignedMath for int256;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        State Variables           ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice ApolloX router used to fetch funding rate and open interest data
    address public immutable apolloXRouter;

    /// @notice User conditions mapped by wallet and condition id
    mapping(address wallet => mapping(uint32 id => Condition condition))
        private conditions;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Constructor         ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @param _apolloXRouter Address of the ApolloX router
    constructor(address _apolloXRouter) {
        apolloXRouter = _apolloXRouter;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Public Functions           ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Adds a new funding-rate condition for the sender
    /// @param _id Unique condition identifier
    /// @param condition Condition configuration
    function addCondition(uint32 _id, Condition calldata condition) external {
        conditions[msg.sender][_id] = condition;

        _addCondition(_id);

        emit ConditionAdded(_id, msg.sender, condition);
    }

    /// @notice Deletes an existing condition
    /// @param _id Condition identifier
    function deleteCondition(
        uint32 _id
    ) public override(BaseCondition, IFundingRateCondition) {
        super.deleteCondition(_id);
        delete conditions[msg.sender][_id];
    }

    /// @notice Indicates whether a condition supports updates
    /// @param _id Condition identifier
    /// @return True if the condition is updateable
    function updateCondition(
        uint32 _id
    )
        public
        view
        override(BaseCondition, IFundingRateCondition)
        returns (bool)
    {
        return conditions[msg.sender][_id].updateable;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃      Internal Functions          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Calculates the funding rate for a pair and position type
    /// @param baseToken Trading pair base token
    /// @param positionType LONG or SHORT position
    /// @return fundingFeeR Calculated funding rate
    /// @return shortQty Total short open interest
    /// @return longQty Total long open interest
    function _calculateFundingRate(
        address baseToken,
        PositionType positionType
    )
        internal
        view
        returns (int256 fundingFeeR, uint256 shortQty, uint256 longQty)
    {
        ITradingCore.PairQty memory ppi = ITradingCore(apolloXRouter)
            .getPairQty(baseToken);

        PairMaxOiAndFundingFeeConfig memory pairConfig = IPairsManager(
            apolloXRouter
        ).getPairConfig(baseToken);

        fundingFeeR =
            int256(
                (int256(ppi.longQty) - int256(ppi.shortQty)).abs() *
                    pairConfig.fundingFeePerBlockP
            ) /
            (int256(ppi.longQty).max(int256(ppi.shortQty)));

        fundingFeeR = int256(pairConfig.maxFundingFeeR).min(
            int256(pairConfig.minFundingFeeR).max(fundingFeeR)
        );

        // Invert funding if shorts dominate and user is long
        if (ppi.longQty > ppi.shortQty && positionType == PositionType.LONG) {
            fundingFeeR = -fundingFeeR;
        }

        if (ppi.shortQty > ppi.longQty && positionType == PositionType.SHORT) {
            fundingFeeR = -fundingFeeR;
        }

        shortQty = ppi.shortQty;
        longQty = ppi.longQty;
    }

    /// @notice Calculates open interest delta percentage
    /// @dev Uses 1000 as fixed-point denominator
    /// @param shortQty Total short open interest
    /// @param longQty Total long open interest
    /// @return deltaPercentage OI imbalance in per-mille
    function _calculateDeltaPercentage(
        uint256 shortQty,
        uint256 longQty
    ) internal pure returns (uint256 deltaPercentage) {
        deltaPercentage =
            uint256((int256(longQty) - int256(shortQty)).abs() * 1000) /
            (shortQty + longQty);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃         View Functions           ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Evaluates whether a condition is satisfied
    /// @param wallet Wallet owning the condition
    /// @param id Condition identifier
    /// @return 1 if condition is met, otherwise 0
    function checkCondition(
        address wallet,
        uint32 id
    )
        public
        view
        override(BaseCondition, IFundingRateCondition)
        returns (uint8)
    {
        Condition memory condition = conditions[wallet][id];

        bool positionActive = ITradingReader(apolloXRouter)
            .getPositionsV2(wallet, condition.baseToken)
            .length > 0;

        if (condition.activePosition != positionActive) {
            return 0;
        }

        (
            int256 fundingFeeR,
            uint256 shortQty,
            uint256 longQty
        ) = _calculateFundingRate(condition.baseToken, condition.positionType);

        if (condition.withDeltaPercentage) {
            uint256 deltaPercentage = _calculateDeltaPercentage(
                shortQty,
                longQty
            );

            if (deltaPercentage < condition.deltaPercentage) {
                return 0;
            }
        }

        if (
            condition.comparison == Comparison.GREATER ||
            condition.comparison == Comparison.GREATER_OR_EQUAL
        ) {
            if (fundingFeeR > condition.fundingRate) return 1;
        }

        if (
            condition.comparison == Comparison.LESS ||
            condition.comparison == Comparison.LESS_OR_EQUAL
        ) {
            if (fundingFeeR < condition.fundingRate) return 1;
        }

        if (
            condition.comparison == Comparison.EQUAL ||
            condition.comparison == Comparison.GREATER_OR_EQUAL ||
            condition.comparison == Comparison.LESS_OR_EQUAL
        ) {
            if (fundingFeeR == condition.fundingRate) return 1;
        }

        if (condition.comparison == Comparison.NOT_EQUAL) {
            if (fundingFeeR != condition.fundingRate) return 1;
        }

        return 0;
    }

    /// @notice Checks whether a condition can be updated
    /// @param wallet Condition owner
    /// @param id Condition identifier
    /// @return True if updateable
    function isUpdateable(
        address wallet,
        uint32 id
    )
        public
        view
        override(BaseCondition, IFundingRateCondition)
        returns (bool)
    {
        return conditions[wallet][id].updateable;
    }

    /// @notice Returns the full condition configuration
    /// @param wallet Condition owner
    /// @param id Condition identifier
    /// @return Condition struct
    function walletCondition(
        address wallet,
        uint32 id
    ) public view returns (Condition memory) {
        return conditions[wallet][id];
    }
}

